import{fs,db}from'./gta-email-recovery-runtime.mjs';import{randomUUID}from'node:crypto';const{db:write}=await import('./reply-runtime-20261007.mjs');const dir='artifacts/abhi-job-20261027/';const file=dir+'sms-receipt.json';const account=process.env.TWILIO_ACCOUNT_SID.trim(),auth='Basic '+Buffer.from(account+':'+process.env.TWILIO_AUTH_TOKEN.trim()).toString('base64');
if(process.argv[2]==='verify'){const r=JSON.parse(fs.readFileSync(file));const res=await fetch(`https://api.twilio.com/2010-04-01/Accounts/${account}/Messages/${r.sid}.json`,{headers:{Authorization:auth}});const data=await res.json();r.delivery={at:new Date().toISOString(),status:data.status,errorCode:data.error_code,errorMessage:data.error_message};fs.writeFileSync(file,JSON.stringify(r,null,2));console.log(JSON.stringify(r.delivery));process.exit(0);}
if(fs.existsSync(file))throw Error('Receipt exists; no duplicate');const review=JSON.parse(fs.readFileSync(dir+'private-review-link.json'));const contact=JSON.parse(fs.readFileSync(dir+'abhi-contact.json'));const[c]=await db('subcontractors',{id:'eq.'+contact.id});if(!c||c.phone!=='+15193293786'||c.status==='blocked'||/OWNER OUTREACH HOLD|IDENTITY REVIEW HOLD|DECLINED|AD-CHANNEL PREFERENCE/.test(c.notes||''))throw Error('Contact changed/held');const messages=await db('sms_messages',{or:'(from_number.eq.'+c.phone+',to_number.eq.'+c.phone+')',order:'created_at.desc',limit:1000});if(messages.length===1000||messages.some(s=>s.direction==='inbound'&&/^(stop|unsubscribe)|not interested|go away|do not (text|contact)|wrong number/i.test(s.body.trim())))throw Error('Suppressed');const peers=await db('market_contacts',{phone:'ilike.*3786*',limit:1000});if(peers.length===1000||peers.some(p=>String(p.phone||'').replace(/\D/g,'').slice(-10)==='5193293786'&&(p.do_not_contact||p.cross_channel_suppressed_at)))throw Error('Suppressed');const response=await fetch(review.url);const html=await response.text();if(!response.ok||!html.includes('Complete recorded inventory')||!html.includes('Abhi'))throw Error('Private link not ready');const body=`Hi Abhi, please review this Kitchener-to-London job for October 30 and let me know your availability and flat price for the full scope. Inventory and access details are here:\n${review.url}\n\nJohn, SSM`;const r={state:'reserved_no_blind_retry',at:new Date().toISOString(),from:'+12262419853',to:c.phone,body,contractorId:c.id,leadId:'lead_ctn74wt50'};fs.writeFileSync(file,JSON.stringify(r,null,2),{flag:'wx'});const resp=await fetch(`https://api.twilio.com/2010-04-01/Accounts/${account}/Messages.json`,{method:'POST',headers:{Authorization:auth,'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({From:r.from,To:r.to,Body:body}),signal:AbortSignal.timeout(25000)});const data=await resp.json();r.sid=data.sid;r.providerResult=data;r.state=resp.ok&&r.sid?'provider_accepted':'failed_or_ambiguous';fs.writeFileSync(file,JSON.stringify(r,null,2));if(!resp.ok||!r.sid)throw Error('Provider failed; no blind retry');const logId=randomUUID();await write('sms_messages',{},'POST',{id:logId,from_number:r.from,to_number:r.to,body,direction:'outbound',lead_id:null,twilio_sid:r.sid,created_at:r.at});if((await db('sms_messages',{id:'eq.'+logId})).length!==1)throw Error('Missing log');r.logId=logId;r.state='accepted_crm_verified';fs.writeFileSync(file,JSON.stringify(r,null,2));const[fresh]=await db('subcontractors',{id:'eq.'+c.id});await write('subcontractors',{id:'eq.'+c.id},'PATCH',{notes:(fresh.notes||'')+'\n\nSCOPE REVIEW SENT 2026-10-20\nMoe job lead_ctn74wt50, recorded move date October 30. Owner confirmed job and requested scope review first. Private review '+review.reviewId+' sent from Kitchener line. No payout or award agreed; contractor remains pending. SMS '+r.sid+'.'});console.log(JSON.stringify({state:r.state,sid:r.sid}));
